          def {{ method.id }}(arg)
            {{ object.id }}.{{ method.id }} arg
          end
        {% else %}
          def {{ method.id }}(*args, **options)
            {{ object.id }}.{{ method.id }}(*args, **options)
          end

          def {{ method.id }}(*args, **options)
            {{ object.id }}.{{ method.id }}(*args, **options) do |*yield_args|
              yield *yield_args
            end
          end
        {% end %}
      {% end %}
    {% else %}
      {% for method in methods %}
        {% if (method.id.ends_with?('=')) && (method.id != "[]=") %}
          def {{ method.id }}(arg)
