          end
        {% else %}
          def {{ method.id }}(*args, **options)
            {{ object.id }}.{{ method.id }}(*args, **options)
          end

          {% if method.id != "[]=" %}
            def {{ method.id }}(*args, **options)
              {{ object.id }}.{{ method.id }}(*args, **options) do |*yield_args|
                yield *yield_args
