    raise("macro `record` does not accept named arguments\n  Did you mean:\n\n  record #{name}, #{((properties + kwargs.map do |name, value| "#{name} : #{value}" end).join(", ")).id}")
  end





  %}

  struct {{ name.id }}
    {% for property in properties %}
      {% if property.is_a?(Assign) %}
        {% if (compare_versions(::Crystal::VERSION, "1.11.0")) >= 0 && (property.doc != "") %}# {{ (property.doc.gsub(/\n/, "\n# ")).id }}{% end %}
        getter {{ property.target.id }}
      {% elsif property.is_a?(TypeDeclaration) %}
        {% if (compare_versions(::Crystal::VERSION, "1.11.0")) >= 0 %}
          {% unless property.doc == "" %}# {{ (property.doc.gsub(/\n/, "\n# ")).id }}{% end %}
          getter {{ property.var.id }} : {{ property.type }}{% if !property.value.nil? || (property.value.stringify == "nil") %} = {{ property.value }}{% end %}
        {% else %}
          getter {{ property }}
        {% end %}
      {% else %}
        {% if (compare_versions(::Crystal::VERSION, "1.11.0")) >= 0 && (property.doc != "") %}# {{ (property.doc.gsub(/\n/, "\n# ")).id }}{% end %}
        getter :{{ property.id }}
      {% end %}
    {% end %}

    def initialize({{ 
    properties.map do |field|
      "@#{field.id}".id
    end.splat
   }})
    end

    {{ yield }}

    def copy_with({{ 
    properties.map do |property|
      if property.is_a?(Assign)
        "#{property.target.id} _#{property.target.id} = @#{property.target.id}".id
      elsif property.is_a?(TypeDeclaration)
        "#{property.var.id} _#{property.var.id} = @#{property.var.id}".id
      else
        "#{property.id} _#{property.id} = @#{property.id}".id
      end
    end.splat
   }})
      self.class.new({{ 
    properties.map do |property|
      if property.is_a?(Assign)
        "_#{property.target.id}".id
      elsif property.is_a?(TypeDeclaration)
        "_#{property.var.id}".id
      else
        "_#{property.id}".id
      end
    end.splat
   }})
    end

    def clone
      self.class.new({{ 
    properties.map do |property|
      if property.is_a?(Assign)
        "@#{property.target.id}.clone".id
      elsif property.is_a?(TypeDeclaration)
        "@#{property.var.id}.clone".id
      else
        "@#{property.id}.clone".id
      end
    end.splat
   }})
    end
  end
end

macro getter(*names, &block)
    {% for name in names %}
      {% if name.is_a?(TypeDeclaration) %}
        {% var_name = name.var.id %}
        {% type = name.type %}
        {% if block %}
          @{{ var_name }} : {{ type }}? {% if name.value %} = {{ name.value }} {% end %}
        {% else %}
          @{{ name }}
        {% end %}
      {% elsif name.is_a?(Assign) %}
        {% var_name = name.target %}
        {% type = nil %}
        @{{ name }}
      {% else %}
        {% var_name = name.id %}
        {% type = nil %}
      {% end %}

      def {{ var_name }} {% if type %} : {{ type }} {% end %}
        {% if block %}
          if (%value = @{{ var_name }}).nil?
            @{{ var_name }} = {{ yield }}
          else
            %value
          end
        {% else %}
          @{{ var_name }}
        {% end %}
      end

    {% end %}
  end

