      {% end %}

      def {{ var_name }} {% if type %} : {{ type }} {% end %}
        {% if block %}
          if (%value = @{{ var_name }}).nil?
            @{{ var_name }} = {{ yield }}
          else
            %value
          end
        {% else %}
          @{{ var_name }}
        {% end %}
